module.exports = "import React, { Component } from 'react';\n\nimport {\n  EuiPopoverTitle,\n  EuiFlexItem,\n  EuiFlexGroup,\n  EuiPopover,\n  EuiSelect,\n  EuiFieldNumber,\n} from '../../../../src/components';\n\nimport { EuiExpression } from '../../../../src/components/expression';\n\n// Rise the popovers above GuidePageSideNav\nconst POPOVER_STYLE = { zIndex: '200' };\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      example1: {\n        isOpen: false,\n        value: 'count()',\n      },\n      example2: {\n        value: 100,\n        description: 'Is above',\n      },\n    };\n  }\n\n  openExample1 = () => {\n    this.setState({\n      example1: {\n        ...this.state.example1,\n        isOpen: true,\n      },\n      example2: {\n        ...this.state.example2,\n        isOpen: false,\n      },\n    });\n  };\n\n  closeExample1 = () => {\n    this.setState({\n      example1: {\n        ...this.state.example1,\n        isOpen: false,\n      },\n    });\n  };\n\n  openExample2 = () => {\n    this.setState({\n      example1: {\n        ...this.state.example1,\n        isOpen: false,\n      },\n      example2: {\n        ...this.state.example2,\n        isOpen: true,\n      },\n    });\n  };\n\n  closeExample2 = () => {\n    this.setState({\n      example2: {\n        ...this.state.example2,\n        isOpen: false,\n      },\n    });\n  };\n\n  changeExample1 = event => {\n    this.setState({\n      example1: { ...this.state.example1, value: event.target.value },\n    });\n  };\n\n  changeExample2Value = e => {\n    const sanitizedValue = parseInt(e.target.value, 10);\n    this.setState({\n      example2: {\n        ...this.state.example2,\n        value: isNaN(sanitizedValue) ? '' : sanitizedValue,\n      },\n    });\n  };\n\n  changeExample2Description = event => {\n    this.setState({\n      example2: { ...this.state.example2, description: event.target.value },\n    });\n  };\n\n  renderPopover1() {\n    return (\n      <div style={POPOVER_STYLE}>\n        <EuiPopoverTitle>When</EuiPopoverTitle>\n        <EuiSelect\n          value={this.state.example1.value}\n          onChange={this.changeExample1}\n          options={[\n            { value: 'count()', text: 'count()' },\n            { value: 'average()', text: 'average()' },\n            { value: 'sum()', text: 'sum()' },\n            { value: 'median()', text: 'median()' },\n            { value: 'min()', text: 'min()' },\n            { value: 'max()', text: 'max()' },\n          ]}\n        />\n      </div>\n    );\n  }\n\n  renderPopover2() {\n    return (\n      <div style={POPOVER_STYLE}>\n        <EuiFlexGroup>\n          <EuiFlexItem grow={false} style={{ width: 150 }}>\n            <EuiSelect\n              value={this.state.example2.description}\n              onChange={this.changeExample2Description}\n              options={[\n                { value: 'Is above', text: 'Is above' },\n                { value: 'Is below', text: 'Is below' },\n                { value: 'Is exactly', text: 'Is exactly' },\n              ]}\n            />\n          </EuiFlexItem>\n\n          <EuiFlexItem grow={false} style={{ width: 100 }}>\n            <EuiFieldNumber\n              value={this.state.example2.value}\n              onChange={this.changeExample2Value}\n            />\n          </EuiFlexItem>\n        </EuiFlexGroup>\n      </div>\n    );\n  }\n\n  render() {\n    return (\n      <EuiFlexGroup gutterSize=\"s\">\n        <EuiFlexItem grow={false}>\n          <EuiPopover\n            id=\"popover1\"\n            button={\n              <EuiExpression\n                description=\"when\"\n                value={this.state.example1.value}\n                isActive={this.state.example1.isOpen}\n                onClick={this.openExample1}\n              />\n            }\n            isOpen={this.state.example1.isOpen}\n            closePopover={this.closeExample1}\n            ownFocus\n            withTitle\n            anchorPosition=\"downLeft\">\n            {this.renderPopover1()}\n          </EuiPopover>\n        </EuiFlexItem>\n\n        <EuiFlexItem grow={false}>\n          <EuiPopover\n            id=\"popover2\"\n            button={\n              <EuiExpression\n                description={this.state.example2.description}\n                value={this.state.example2.value}\n                isActive={this.state.example2.isOpen}\n                onClick={this.openExample2}\n              />\n            }\n            isOpen={this.state.example2.isOpen}\n            closePopover={this.closeExample2}\n            ownFocus\n            anchorPosition=\"downLeft\">\n            {this.renderPopover2()}\n          </EuiPopover>\n        </EuiFlexItem>\n      </EuiFlexGroup>\n    );\n  }\n}\n"