module.exports = "import React from 'react';\n\nimport {\n  EuiBadge,\n  EuiFlexItem,\n  EuiFlexGroup,\n} from '../../../../src/components';\n\nconst badges = [\n  'default',\n  'hollow',\n  'primary',\n  'secondary',\n  'accent',\n  'warning',\n  'danger',\n  '#fea27f',\n  '#000',\n];\n\nexport default () => (\n  <EuiFlexGroup wrap responsive={false} gutterSize=\"xs\" style={{ width: 300 }}>\n    {badges.map(badge => (\n      <EuiFlexItem grow={false} key={badge}>\n        <EuiBadge color={badge}>{badge}</EuiBadge>\n      </EuiFlexItem>\n    ))}\n  </EuiFlexGroup>\n);\n"