module.exports = "import React, { Component } from 'react';\n\nimport { EuiComboBox, EuiFormRow } from '../../../../src/components';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.options = [\n      {\n        label: 'Titan',\n        'data-test-subj': 'titanOption',\n      },\n      {\n        label: 'Enceladus',\n      },\n      {\n        label: 'Mimas',\n      },\n      {\n        label: 'Dione',\n      },\n      {\n        label: 'Iapetus',\n      },\n      {\n        label: 'Phoebe',\n      },\n      {\n        label: 'Rhea',\n      },\n      {\n        label:\n          \"Pandora is one of Saturn's moons, named for a Titaness of Greek mythology\",\n      },\n      {\n        label: 'Tethys',\n      },\n      {\n        label: 'Hyperion',\n      },\n    ];\n\n    this.state = {\n      error: undefined,\n      selectedOptions: [this.options[2], this.options[4]],\n    };\n  }\n\n  onChange = selectedOptions => {\n    this.setState({\n      error: undefined,\n      selectedOptions,\n    });\n  };\n\n  onSearchChange = (value, hasMatchingOptions) => {\n    this.setState({\n      error:\n        value.length === 0 || hasMatchingOptions\n          ? undefined\n          : `\"${value}\" is not a valid option`,\n    });\n  };\n\n  onBlur = () => {\n    const { value } = this.inputRef;\n    this.setState({\n      error:\n        value.length === 0 ? undefined : `\"${value}\" is not a valid option`,\n    });\n  };\n\n  setInputRef = ref => (this.inputRef = ref);\n\n  render() {\n    return (\n      <EuiFormRow\n        error={this.state.error}\n        isInvalid={this.state.error !== undefined}>\n        <EuiComboBox\n          placeholder=\"Select from a list of options\"\n          options={this.options}\n          selectedOptions={this.state.selectedOptions}\n          inputRef={this.setInputRef}\n          onChange={this.onChange}\n          onSearchChange={this.onSearchChange}\n          onBlur={this.onBlur}\n        />\n      </EuiFormRow>\n    );\n  }\n}\n"