module.exports = "import React, { Component, Fragment } from 'react';\nimport { formatDate } from '../../../../../src/services/format';\nimport { createDataStore } from '../data_store';\nimport {\n  EuiInMemoryTable,\n  EuiLink,\n  EuiHealth,\n  EuiSpacer,\n  EuiSwitch,\n  EuiFlexGroup,\n  EuiFlexItem,\n} from '../../../../../src/components';\n\n/*\nExample user object:\n\n{\n  id: '1',\n  firstName: 'john',\n  lastName: 'doe',\n  github: 'johndoe',\n  dateOfBirth: Date.now(),\n  nationality: 'NL',\n  online: true\n}\n\nExample country object:\n\n{\n  code: 'NL',\n  name: 'Netherlands',\n  flag: '🇳🇱'\n}\n*/\n\nconst store = createDataStore();\n\nexport class Table extends Component {\n  constructor(props) {\n    super(props);\n    this.state = {\n      incremental: false,\n      filters: false,\n    };\n  }\n\n  render() {\n    const columns = [\n      {\n        field: 'firstName',\n        name: 'First Name',\n        sortable: true,\n        truncateText: true,\n      },\n      {\n        field: 'lastName',\n        name: 'Last Name',\n        truncateText: true,\n      },\n      {\n        field: 'github',\n        name: 'Github',\n        render: username => (\n          <EuiLink href={`https://github.com/${username}`} target=\"_blank\">\n            {username}\n          </EuiLink>\n        ),\n      },\n      {\n        field: 'dateOfBirth',\n        name: 'Date of Birth',\n        dataType: 'date',\n        render: date => formatDate(date, 'dobLong'),\n        sortable: true,\n      },\n      {\n        field: 'nationality',\n        name: 'Nationality',\n        render: countryCode => {\n          const country = store.getCountry(countryCode);\n          return `${country.flag} ${country.name}`;\n        },\n      },\n      {\n        field: 'online',\n        name: 'Online',\n        dataType: 'boolean',\n        render: online => {\n          const color = online ? 'success' : 'danger';\n          const label = online ? 'Online' : 'Offline';\n          return <EuiHealth color={color}>{label}</EuiHealth>;\n        },\n      },\n      {\n        field: 'nationality',\n        name: 'Nationality',\n        render: countryCode => {\n          const country = store.getCountry(countryCode);\n          return `${country.flag} ${country.name}`;\n        },\n      },\n      {\n        field: 'online',\n        name: 'Online',\n        dataType: 'boolean',\n        render: online => {\n          const color = online ? 'success' : 'danger';\n          const label = online ? 'Online' : 'Offline';\n          return <EuiHealth color={color}>{label}</EuiHealth>;\n        },\n        sortable: true,\n      },\n    ];\n\n    const search = {\n      box: {\n        incremental: this.state.incremental,\n        schema: true,\n      },\n      filters: !this.state.filters\n        ? undefined\n        : [\n            {\n              type: 'is',\n              field: 'online',\n              name: 'Online',\n              negatedName: 'Offline',\n            },\n            {\n              type: 'field_value_selection',\n              field: 'nationality',\n              name: 'Nationality',\n              multiSelect: false,\n              options: store.countries.map(country => ({\n                value: country.code,\n                name: country.name,\n                view: `${country.flag} ${country.name}`,\n              })),\n            },\n          ],\n    };\n\n    return (\n      <Fragment>\n        <EuiFlexGroup>\n          <EuiFlexItem grow={false}>\n            <EuiSwitch\n              label=\"Incremental\"\n              checked={this.state.incremental}\n              onChange={() =>\n                this.setState(prevState => ({\n                  incremental: !prevState.incremental,\n                }))\n              }\n            />\n          </EuiFlexItem>\n          <EuiFlexItem grow={false}>\n            <EuiSwitch\n              label=\"With Filters\"\n              checked={this.state.filters}\n              onChange={() =>\n                this.setState(prevState => ({ filters: !prevState.filters }))\n              }\n            />\n          </EuiFlexItem>\n        </EuiFlexGroup>\n        <EuiSpacer size=\"l\" />\n        <EuiInMemoryTable\n          items={store.users}\n          columns={columns}\n          search={search}\n          pagination={true}\n          sorting={true}\n        />\n      </Fragment>\n    );\n  }\n}\n"