module.exports = "import React, { Component } from 'react';\n\nimport {\n  EuiButton,\n  EuiContextMenuPanel,\n  EuiPopover,\n} from '../../../../src/components';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.interval = undefined;\n\n    this.state = {\n      isPopoverOpen: false,\n    };\n  }\n\n  onButtonClick = () => {\n    this.setState(prevState => ({\n      isPopoverOpen: !prevState.isPopoverOpen,\n    }));\n  };\n\n  closePopover = () => {\n    this.setState({\n      isPopoverOpen: false,\n    });\n  };\n\n  render() {\n    const button = (\n      <EuiButton\n        size=\"s\"\n        iconType=\"arrowDown\"\n        iconSide=\"right\"\n        onClick={this.onButtonClick}>\n        Click to show some content\n      </EuiButton>\n    );\n\n    return (\n      <EuiPopover\n        id=\"contentPanel\"\n        button={button}\n        isOpen={this.state.isPopoverOpen}\n        closePopover={this.closePopover}\n        panelPaddingSize=\"s\"\n        anchorPosition=\"downLeft\">\n        <EuiContextMenuPanel>\n          This context menu doesn&#39;t render items, it passes a child instead.\n        </EuiContextMenuPanel>\n      </EuiPopover>\n    );\n  }\n}\n"